#!/usr/bin/env node
// Claude Code PreToolUse hook (Edit, Write, MultiEdit) — generated by KeelWright.
// Blocks, with a reason Claude can act on:
//   - changes to an accepted ADR (only its status may change, to "superseded by ADR-NNNN" or "deprecated")
//   - edits to generated files (e.g. the theme generated from design/tokens.json)
//   - new content that gitleaks detects as a secret (when gitleaks is installed)
// Exit 0 allows the edit; exit 2 blocks it and shows stderr to Claude.

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { relative, resolve } from 'node:path';

const GENERATED = /^\/\* Generated from (\S+) by KeelWright/;

function readInput() {
  try {
    return JSON.parse(readFileSync(0, 'utf8'));
  } catch {
    return null;
  }
}

function block(message) {
  process.stderr.write(`${message}\n`);
  process.exit(2);
}

// The text this edit would add, for the secret scan.
function newText(tool) {
  if (typeof tool.content === 'string') return tool.content;
  if (typeof tool.new_string === 'string') return tool.new_string;
  if (Array.isArray(tool.edits)) return tool.edits.map((e) => e.new_string ?? '').join('\n');
  return '';
}

const statusLine = (text) => /^status:\s*(.+)$/m.exec(text)?.[1]?.trim() ?? null;

function checkAdr(file, tool, rel) {
  if (!/(^|\/)docs\/decisions\/\d{4}-[^/]+\.md$/.test(rel) || !existsSync(file)) return;
  const current = readFileSync(file, 'utf8');
  if (statusLine(current) !== 'accepted') return;
  // Allowed: an edit that only changes the status line to superseded / deprecated.
  const edits = Array.isArray(tool.edits) ? tool.edits : [{ old_string: tool.old_string, new_string: tool.new_string }];
  const onlyStatus = edits.every((e) => typeof e.old_string === 'string' && /^status:/m.test(e.old_string) && e.old_string.trim().split('\n').length === 1 && /^status:\s*(superseded by ADR-\d{4}|deprecated)\s*$/m.test(e.new_string ?? ''));
  if (typeof tool.content !== 'string' && onlyStatus) return;
  block(`${rel} is an accepted ADR and must not be changed. Write a new ADR that supersedes it (copy docs/decisions/0001-*.md's structure), then set this ADR's status to "superseded by ADR-NNNN".`);
}

function checkGenerated(file, rel) {
  if (!existsSync(file)) return;
  const m = GENERATED.exec(readFileSync(file, 'utf8').slice(0, 300));
  if (m) block(`${rel} is generated from ${m[1]} — edit ${m[1]} instead and regenerate it (npm run tokens).`);
}

function checkSecrets(text, rel) {
  if (!text.trim()) return;
  const r = spawnSync('gitleaks', ['stdin', '--no-banner', '--redact', '--log-level', 'error'], { input: text, encoding: 'utf8' });
  if (r.error) return; // gitleaks not installed: the pre-commit hook and CI still scan
  if (r.status === 1) block(`Possible secret in the new content for ${rel} (gitleaks). Read it from an environment variable instead and list the variable in .env.example.\n${(r.stdout || r.stderr).trim()}`);
}

const input = readInput();
const tool = input?.tool_input ?? {};
if (!tool.file_path) process.exit(0);
const root = process.env.CLAUDE_PROJECT_DIR ?? input.cwd ?? process.cwd();
const file = resolve(root, tool.file_path);
const rel = relative(root, file).split('\\').join('/');

checkAdr(file, tool, rel);
checkGenerated(file, rel);
checkSecrets(newText(tool), rel);
process.exit(0);
